+                    return;
+                }
+                if (sameFile(target, index)) {
+                    return;
+                }
+                Files.delete(target);
+                try {
+                    Files.delete(entry.path);
+                } catch (IOException e) {
+                    try {
+                        Files.createSymbolicLink(entry.path, target);
+                    } catch (IOException ignored) {
