        private boolean regular;
        private boolean direct;
        private boolean noViolations;
        private boolean broken;
        private boolean shared;
        private boolean colliding;
        private boolean misplaced;
        private boolean occupied;
        private boolean leadsToIndex;

        private Entry(String description, String name, String derivedName) {
            this.description = description;
            this.name = name;
            this.derivedName = derivedName;
        }

        private boolean resolved() {
            return !broken && noViolations;
        }
    }

    private static final class IntegrityReport {
        private final FolderContext context;
        private final List<Entry> entries;
        private final List<Path> unownedFiles;

        private IntegrityReport(FolderContext context, List<Entry> entries, List<Path> unownedFiles) {
            this.context = context;
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        private boolean hasProblems() {
            return entries.stream().anyMatch(entry -> entry.broken || entry.resolved() || entry.shared || entry.misplaced
                    || entry.colliding || entry.occupied) || !unownedFiles.isEmpty();
        }

        private String failureMessage() {
            List<Entry> sorted = new ArrayList<>(entries);
            sorted.sort(Comparator.comparing(entry -> entry.description));
            StringBuilder result = new StringBuilder("Violation store integrity check failed:");
            appendEntries(result, "broken", sorted, entry -> entry.broken);
            appendEntries(result, "resolved", sorted, Entry::resolved);
            appendEntries(result, "shared", sorted, entry -> entry.shared);
            if (!unownedFiles.isEmpty()) {
                result.append("\nunowned files:");
                for (Path file : unownedFiles) {
                    result.append("\n- ").append(file.getFileName());
                }
            }
            appendEntries(result, "misplaced", sorted, entry -> entry.misplaced);
            appendEntries(result, "colliding", sorted, entry -> entry.colliding);
            appendEntries(result, "occupied", sorted, entry -> entry.occupied);
            return result.toString();
        }

        private static void appendEntries(StringBuilder result, String condition, List<Entry> entries, EntryCondition predicate) {
            List<Entry> matching = entries.stream().filter(predicate::matches).collect(toList());
            if (matching.isEmpty()) {
                return;
            }
            result.append("\n").append(condition).append(" entries:");
            for (Entry entry : matching) {
                result.append("\n- ").append(entry.description).append(" -> ").append(entry.name);
            }
        }
    }

    @FunctionalInterface
    private interface EntryCondition {
        boolean matches(Entry entry);
    }

