+import static com.tngtech.archunit.library.freeze.FreezingArchRule.ensureUnixLineBreaks;
+import static java.nio.charset.StandardCharsets.UTF_8;
+import static java.util.stream.Collectors.toList;
+
+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ * <p>
+ * The store can be configured through the following properties:
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=...          # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=...          # ignore, repair, or fail
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_RANDOM = "random";
+    private static final String FILE_NAMES_DESCRIPTION = "description";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_IGNORE = "ignore";
+    private static final String INTEGRITY_REPAIR = "repair";
+    private static final String INTEGRITY_FAIL = "fail";
+
+    /*
+     * The lock is deliberately shared by all instances in this VM.  In particular, an
+     * initializing store must not inspect the directory while another store is replacing
+     * a violation file or the index.
+     */
+    private static final ConcurrentHashMap<String, StoreState> STORE_STATES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean hasConstructorStrategy;
+
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private IntegrityMode integrityMode;
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private StoreState storeState;
+
+    /**
+     * Creates a standard store that names rule violation files randomly by {@link UUID}.
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+        hasConstructorStrategy = false;
+    }
+
+    /**
+     * Creates a store with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new IllegalArgumentException("Rule violation file name strategy must not be null");
+        }
+        constructorStrategy = ruleViolationFileNameStrategy;
+        hasConstructorStrategy = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        if (properties == null) {
+            throw new StoreInitializationFailedException("Store properties must not be null");
+        }
+
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE));
+        ruleViolationFileNameStrategy = configureFileNameStrategy(properties);
+
+        Path folder = Paths.get(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).toAbsolutePath().normalize();
+        Path storedRulesFile = folder.resolve(STORED_RULES_FILE_NAME);
+        StoreState state = getStoreState(storedRulesFile);
+
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile);
+        synchronized (state.lock) {
+            boolean indexExists = existsWithoutFollowingLinks(storedRulesFile);
+            if (!indexExists && !storeCreationAllowed) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+            validateFolder(folder);
+            if (indexExists && !Files.isRegularFile(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Stored rules index must be a regular file directly in the store folder: %s", storedRulesFile));
+            }
+
+            Properties propertiesFromIndex = indexExists ? loadProperties(storedRulesFile) : new Properties();
+            IntegrityReport report = analyze(folder, storedRulesFile, propertiesFromIndex);
+
+            if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
+                throw new StoreInitializationFailedException(report.failureMessage());
+            }
+            if (integrityMode == IntegrityMode.REPAIR) {
+                repair(report, propertiesFromIndex);
+            }
+
+            ensureFolderAndIndexExist(folder, storedRulesFile);
+            state.properties = loadProperties(storedRulesFile);
+        }
+
+        storeFolder = folder.toFile();
+        storeState = state;
+    }
+
+    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
+        if (hasConstructorStrategy) {
+            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
+                throw new StoreInitializationFailedException(
+                        "Property " + FILE_NAMES_PROPERTY_NAME + " cannot be configured for a store with a constructor file name strategy");
+            }
+            return constructorStrategy;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            return ignored -> UUID.randomUUID().toString();
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return TextFileBasedViolationStore::descriptionBasedFileName;
+        }
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            Constructor<?> constructor = strategyType.getConstructor();
+            Object strategy = constructor.newInstance();
+            if (!(strategy instanceof RuleViolationFileNameStrategy)) {
+                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
+            }
+            return (RuleViolationFileNameStrategy) strategy;
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException | LinkageError e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s; it must be a public no-argument implementation",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private static String descriptionBasedFileName(String description) {
+        String normalized = ensureUnixLineBreaks(description);
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(normalized);
+        String keptWord = null;
+        while (matcher.find()) {
+            // Keeping the last qualifying word means useful rule names are retained even
+            // when a framework-generated prefix makes the description very long.
+            keptWord = matcher.group(1);
+        }
+        String hash = sha256(normalized);
+        String prefix = keptWord == null ? "rule" : keptWord;
+        String result = prefix + "-" + hash;
+        return "stored.rules".equals(result) ? "rule-" + hash : result;
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte b : digest) {
+                result.append(String.format("%02x", b & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    private StoreState getStoreState(Path storedRulesFile) {
+        try {
+            String canonicalPath = storedRulesFile.toFile().getCanonicalPath();
+            return STORE_STATES_BY_PATH.computeIfAbsent(canonicalPath, ignored -> new StoreState(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void validateFolder(Path folder) {
+        if (existsWithoutFollowingLinks(folder) && !Files.isDirectory(folder)) {
+            throw new StoreInitializationFailedException(String.format("Store path is not a folder: %s", folder));
+        }
+    }
+
+    private void ensureFolderAndIndexExist(Path folder, Path storedRulesFile) {
+        try {
+            Files.createDirectories(folder);
+            if (!existsWithoutFollowingLinks(storedRulesFile)) {
+                Files.createFile(storedRulesFile);
+            }
+            if (!Files.isRegularFile(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Stored rules index must be a regular file directly in the store folder: %s", storedRulesFile));
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private static Properties loadProperties(Path file) {
+        Properties result = new Properties();
+        try (InputStream inputStream = Files.newInputStream(file)) {
+            result.load(inputStream);
+            return result;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private IntegrityReport analyze(Path folder, Path storedRulesFile, Properties properties) {
+        FolderContext context = new FolderContext(folder, storedRulesFile);
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String name = properties.getProperty(description);
+            String derivedName = deriveName(description, false);
+            Entry entry = new Entry(description, name, derivedName);
+            inspectEntry(entry, context);
+            entries.add(entry);
+        }
+
+        markShared(entries);
+        markColliding(entries);
+        for (Entry entry : entries) {
+            entry.misplaced = !entry.name.equals(entry.derivedName);
+            entry.occupied = entry.misplaced && !isSameName(entry.name, entry.derivedName)
+                    && isOccupied(entry, entries, context);
+        }
+        return new IntegrityReport(context, entries, findUnownedFiles(context, entries));
+    }
+
+    private String deriveName(String description, boolean forSave) {
+        String name;
+        try {
+            name = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            if (forSave) {
+                throw new StoreUpdateFailedException(e);
+            }
+            throw new StoreInitializationFailedException(e);
+        }
+        if (name == null || name.trim().isEmpty()) {
+            String message = "Rule violation file name strategy returned no name for rule description '" + description + "'";
+            if (forSave) {
+                throw new StoreUpdateFailedException(message);
+            }
+            throw new StoreInitializationFailedException(message);
+        }
+        return name;
+    }
+
+    private void inspectEntry(Entry entry, FolderContext context) {
+        try {
+            entry.path = resolveName(context.folder, entry.name);
+        } catch (InvalidPathException e) {
+            entry.broken = true;
+            return;
+        }
+
+        try {
+            entry.existsWithoutFollowingLinks = existsWithoutFollowingLinks(entry.path);
+            entry.regular = Files.isRegularFile(entry.path);
+            if (entry.regular) {
+                entry.identity = entry.path.toRealPath();
+                entry.direct = isDirectFile(entry.path, context);
+                entry.leadsToIndex = sameFile(entry.path, context.index);
+                entry.noViolations = fileContainsNoViolations(entry.path);
+            }
+            entry.broken = !entry.regular || !entry.direct;
+        } catch (IOException | SecurityException e) {
+            entry.broken = true;
+        }
+    }
+
+    private static Path resolveName(Path folder, String name) {
+        return folder.resolve(Paths.get(name));
+    }
+
+    private static boolean isDirectFile(Path path, FolderContext context) throws IOException {
+        Path candidate = path;
+        Path parent = context.folder.toAbsolutePath().normalize();
+        if (candidate.isAbsolute() || candidate.getNameCount() != 1) {
+            return false;
+        }
+        Path realPath = path.toRealPath();
+        return realPath.getParent() != null && realPath.getParent().equals(context.realFolder)
+                && path.normalize().getParent() != null && path.normalize().getParent().equals(parent);
+    }
+
+    private static boolean fileContainsNoViolations(Path path) throws IOException {
+        byte[] content = Files.readAllBytes(path);
+        for (byte current : content) {
+            if (current != '\n' && current != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private static void markShared(List<Entry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry first = entries.get(i);
+                Entry second = entries.get(j);
+                if (first.name.equals(second.name) || sameFile(first.path, second.path)) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+    }
+
+    private static void markColliding(List<Entry> entries) {
+        Map<String, Integer> counts = new HashMap<>();
+        for (Entry entry : entries) {
+            counts.put(entry.derivedName, counts.getOrDefault(entry.derivedName, 0) + 1);
+        }
+        for (Entry entry : entries) {
+            entry.colliding = counts.get(entry.derivedName) > 1;
+        }
+    }
+
+    private static boolean isSameName(String first, String second) {
+        return first.equals(second);
+    }
+
+    private static boolean isOccupied(Entry entry, List<Entry> entries, FolderContext context) {
+        try {
+            Path derivedPath = resolveName(context.folder, entry.derivedName);
+            if (derivedPath.isAbsolute() || derivedPath.getNameCount() != 1) {
+                return true;
+            }
+            for (Entry other : entries) {
+                if (other != entry && sameLexicalPath(derivedPath, other.path)) {
+                    return true;
+                }
+            }
+            if (existsWithoutFollowingLinks(derivedPath)) {
+                return true;
+            }
+            return false;
+        } catch (InvalidPathException e) {
+            return true;
+        }
+    }
+
+    private static boolean sameLexicalPath(Path first, Path second) {
+        return first != null && second != null && first.toAbsolutePath().normalize().equals(second.toAbsolutePath().normalize());
+    }
+
+    private static List<Path> findUnownedFiles(FolderContext context, List<Entry> entries) {
+        if (!Files.isDirectory(context.folder)) {
+            return Collections.emptyList();
+        }
+        List<Path> result = new ArrayList<>();
+        try (DirectoryStream<Path> children = Files.newDirectoryStream(context.folder)) {
+            for (Path child : children) {
+                if (sameLexicalPath(child, context.index) || !Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (Entry entry : entries) {
+                    if (sameFile(entry.path, child)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(child);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return result;
+    }
+
+    private void repair(IntegrityReport report, Properties properties) {
+        if (!storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires updating the violation store (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        Properties repaired = copyOf(properties);
+        boolean changed = false;
+        for (Entry entry : report.entries) {
+            if (entry.shared || entry.leadsToIndex) {
+                continue;
+            }
+            if (entry.broken) {
+                changed |= repaired.remove(entry.description) != null;
+            } else if (entry.resolved()) {
+                deleteEntryFile(entry, report.context.index);
+                changed |= repaired.remove(entry.description) != null;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveEntryFile(entry, report.context);
+                repaired.remove(entry.description);
+                repaired.setProperty(entry.description, entry.derivedName);
+                changed = true;
+            }
+        }
+
+        if (changed) {
+            writeProperties(report.context.index, repaired);
+        }
+    }
+
+    private static Properties copyOf(Properties source) {
+        Properties result = new Properties();
+        result.putAll(source);
+        return result;
+    }
+
+    private static void deleteEntryFile(Entry entry, Path index) {
+        if (entry.path == null || !existsWithoutFollowingLinks(entry.path)) {
+            return;
+        }
+        if (sameFile(entry.path, index)) {
+            return;
+        }
+        try {
+            if (Files.isSymbolicLink(entry.path)) {
+                Path target;
+                try {
+                    target = entry.path.toRealPath();
+                } catch (IOException e) {
+                    Files.deleteIfExists(entry.path);
+                    return;
+                }
+                if (sameFile(target, index)) {
+                    return;
+                }
+                Files.delete(target);
+                try {
+                    Files.delete(entry.path);
+                } catch (IOException e) {
+                    try {
+                        Files.createSymbolicLink(entry.path, target);
+                    } catch (IOException ignored) {
+                        // The original target has already been removed. Preserve the
+                        // original exception as the actionable failure.
+                    }
+                    throw e;
+                }
+            } else {
+                Files.delete(entry.path);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private static void moveEntryFile(Entry entry, FolderContext context) {
+        if (entry.path == null || !existsWithoutFollowingLinks(entry.path)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot repair misplaced rule '%s': file '%s' does not exist", entry.description, entry.name));
+        }
+        Path destination = context.folder.resolve(Paths.get(entry.derivedName));
+        try {
+            if (Files.isSymbolicLink(entry.path)) {
+                Path target = entry.path.toRealPath();
+                Files.move(target, destination);
+                try {
+                    Files.delete(entry.path);
+                } catch (IOException e) {
+                    try {
+                        Files.move(destination, target);
+                    } catch (IOException ignored) {
+                        // Keep the original error; initialization will fail rather than
+                        // silently changing the index to an uncertain state.
+                    }
+                    throw e;
+                }
+            } else {
+                Files.move(entry.path, destination);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private static void writeProperties(Path propertiesFile, Properties properties) {
+        Path parent = propertiesFile.getParent();
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(parent, ".stored.rules-", ".tmp");
+            try (OutputStream outputStream = Files.newOutputStream(temporary, StandardOpenOption.TRUNCATE_EXISTING)) {
+                properties.store(outputStream, "");
+            }
+            try {
+                Files.move(temporary, propertiesFile, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+            } catch (AtomicMoveNotSupportedException e) {
+                Files.move(temporary, propertiesFile, StandardCopyOption.REPLACE_EXISTING);
+            }
+            temporary = null;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        } finally {
+            if (temporary != null) {
+                try {
+                    Files.deleteIfExists(temporary);
+                } catch (IOException ignored) {
+                    // There is no useful recovery action for a temporary file here.
+                }
+            }
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronizedStore(() -> {
+            storeState.properties = loadProperties(storeState.index);
+            return findEntry(storeState.properties, rule.getDescription()) != null;
+        });
+        return findEntry(storeState.properties, rule.getDescription()) != null;
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        requireInitialized();
+        synchronized (storeState.lock) {
+            storeState.properties = loadProperties(storeState.index);
+            Entry knownEntry = findEntry(storeState.properties, rule.getDescription());
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && knownEntry != null) {
+                forgetKnownRule(knownEntry);
+                return;
+            }
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                // Repair mode deliberately does not create empty entries for unknown rules.
+                return;
+            }
+
+            String fileName = knownEntry == null ? deriveName(rule.getDescription(), true) : knownEntry.name;
+            Path violationFile = validateSaveTarget(fileName, knownEntry == null);
+            if (knownEntry == null) {
+                writeViolationFile(violationFile, violations);
+                Properties updated = copyOf(storeState.properties);
+                updated.setProperty(rule.getDescription(), fileName);
+                try {
+                    writeProperties(storeState.index, updated);
+                } catch (RuntimeException e) {
+                    try {
+                        Files.deleteIfExists(violationFile);
+                    } catch (IOException ignored) {
+                        // Keep the index unchanged; the caller still gets the failed save.
+                    }
+                    throw new StoreUpdateFailedException(e);
+                }
+                storeState.properties = updated;
+            } else {
+                writeViolationFile(violationFile, violations);
+            }
+        }
+    }
+
+    private void forgetKnownRule(Entry knownEntry) {
+        List<Entry> entries = entriesWithoutDerivedNames(storeState.properties);
+        knownEntry.shared = sharesFile(knownEntry, entries);
+        if (!knownEntry.shared) {
+            deleteFileForSave(knownEntry);
+        }
+        Properties updated = copyOf(storeState.properties);
+        updated.remove(knownEntry.description);
+        try {
+            writeProperties(storeState.index, updated);
+        } catch (RuntimeException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+        storeState.properties = updated;
+    }
+
+    private List<Entry> entriesWithoutDerivedNames(Properties properties) {
+        List<Entry> result = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            result.add(new Entry(description, properties.getProperty(description), properties.getProperty(description)));
+        }
+        return result;
+    }
+
+    private static boolean sharesFile(Entry candidate, List<Entry> entries) {
+        for (Entry other : entries) {
+            if (candidate != other && (candidate.name.equals(other.name) || sameFile(resolvePossiblyInvalid(candidate), resolvePossiblyInvalid(other)))) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private static Path resolvePossiblyInvalid(Entry entry) {
+        return entry.path;
+    }
+
+    private void deleteFileForSave(Entry entry) {
+        if (entry.name == null) {
+            return;
+        }
+        Path path;
+        try {
+            path = resolveName(storeFolder.toPath(), entry.name);
+        } catch (InvalidPathException e) {
+            return;
+        }
+        if (sameFile(path, storeState.index)) {
+            throw new StoreUpdateFailedException("Cannot remove a rule whose violation file is the stored rules index");
+        }
+        if (!existsWithoutFollowingLinks(path)) {
+            return;
+        }
+        try {
+            if (Files.isSymbolicLink(path)) {
+                Path target;
+                try {
+                    target = path.toRealPath();
+                } catch (IOException e) {
+                    Files.delete(path);
+                    return;
+                }
+                if (sameFile(target, storeState.index)) {
+                    throw new StoreUpdateFailedException("Cannot remove a rule whose violation file is the stored rules index");
+                }
+                Files.delete(target);
+                try {
+                    Files.delete(path);
+                } catch (IOException e) {
+                    try {
